from pypdf import PdfReader
import re
r=PdfReader('manuscript.pdf')
terms=['code','github','reproduc','limitation','ethic','experiment','resnet','cifar','seed','hyperparameter','runtime','compute','risk','broader impact']
for term in terms:
    hits=[]
    for i,p in enumerate(r.pages,1):
        t=p.extract_text() or ''
        if re.search(term,t,re.I):
            snippets=[]
            for m in re.finditer(term,t,re.I):
                a=max(0,m.start()-90); b=min(len(t),m.end()+180)
                snippets.append(' '.join(t[a:b].split()))
            hits.append((i,snippets[:3]))
    print('\\nTERM',term,'PAGES',[i for i,_ in hits])
    for i,s in hits:
        for x in s: print(f'  p{i}: {x}')
